const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define region around North Crimean Canal
  const canal = ee.Geometry.Point([33.8, 46.0]).buffer(10000); // 10km buffer around canal area

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get image for June 3, 2023
  const date1 = '2023-06-03';
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(canal)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .map(maskS2clouds);

  const size1 = col1.size().getInfo();
  console.log('June 3 images found: ' + size1);

  if (size1 === 0) {
    // Try wider date range
    const col1_wider = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canal)
      .filterDate('2023-06-01', '2023-06-05')
      .map(maskS2clouds);
    const size1_wider = col1_wider.size().getInfo();
    console.log('June 1-5 images found: ' + size1_wider);
    if (size1_wider === 0) {
      console.log('No data for early June 2023');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get image for July 19, 2023
  const date2 = '2023-07-19';
  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(canal)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .map(maskS2clouds);

  const size2 = col2.size().getInfo();
  console.log('July 19 images found: ' + size2);

  if (size2 === 0) {
    // Try wider date range
    const col2_wider = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canal)
      .filterDate('2023-07-17', '2023-07-21')
      .map(maskS2clouds);
    const size2_wider = col2_wider.size().getInfo();
    console.log('July 17-21 images found: ' + size2_wider);
    if (size2_wider === 0) {
      console.log('No data for mid-July 2023');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Calculate NDVI for both periods
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const img1 = (size1 > 0 ? col1 : ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canal)
      .filterDate('2023-06-01', '2023-06-05')
      .map(maskS2clouds))
    .map(addNDVI)
    .median();

  const img2 = (size2 > 0 ? col2 : ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canal)
      .filterDate('2023-07-17', '2023-07-21')
      .map(maskS2clouds))
    .map(addNDVI)
    .median();

  // Check pixel counts
  const count1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canal,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canal,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log('June valid pixels: ' + count1);
  console.log('July valid pixels: ' + count2);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean NDVI
  const ndvi1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canal,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canal,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log('June NDVI: ' + (ndvi1 !== null ? ndvi1.toFixed(3) : 'null'));
  console.log('July NDVI: ' + (ndvi2 !== null ? ndvi2.toFixed(3) : 'null'));

  if (ndvi1 === null || ndvi2 === null || ndvi1 > 1 || ndvi1 < -1 || ndvi2 > 1 || ndvi2 < -1) {
    console.log('Invalid NDVI calculation');
    console.log('<answer>C3</answer>');
    return;
  }

  const ndviChange = ndvi2 - ndvi1;
  console.log('NDVI change: ' + ndviChange.toFixed(3));

  // Browner means NDVI decreased (less green vegetation)
  if (ndviChange < -0.05) {
    console.log('Vegetation became browner (NDVI decreased)');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation did not become significantly browner');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
